package com.sponsormatch.service;
import com.sponsormatch.dto.CampaignDtos.*; import com.sponsormatch.entity.*; import com.sponsormatch.exception.ApiException; import com.sponsormatch.repository.*; import lombok.RequiredArgsConstructor; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import java.util.*;
@Service @RequiredArgsConstructor public class CampaignService {private final CampaignRepository campaigns;private final UserRepository users; public CampaignResponse create(Long uid,CampaignRequest r){return map(campaigns.save(apply(new Campaign(),r,brand(uid))));} public List<CampaignResponse> mine(Long uid){brand(uid);return campaigns.findByBrandId(uid).stream().map(this::map).toList();} public CampaignResponse get(Long id){return map(find(id));} public CampaignResponse update(Long uid,Long id,CampaignRequest r){Campaign c=owned(uid,id);return map(campaigns.save(apply(c,r,c.getBrand())));}public void delete(Long uid,Long id){campaigns.delete(owned(uid,id));}public Campaign owned(Long uid,Long id){Campaign c=find(id);if(!c.getBrand().getId().equals(uid))throw new ApiException(HttpStatus.FORBIDDEN,"You do not own this campaign");return c;} public Campaign find(Long id){return campaigns.findById(id).orElseThrow(()->new ApiException(HttpStatus.NOT_FOUND,"Campaign not found"));}private User brand(Long id){User u=users.findById(id).orElseThrow(()->new ApiException(HttpStatus.UNAUTHORIZED,"User not found"));if(u.getRole()!=Role.BRAND)throw new ApiException(HttpStatus.FORBIDDEN,"Brand role required");return u;}private Campaign apply(Campaign c,CampaignRequest r,User b){if(r.maxFollowers()!=null&&r.minFollowers()!=null&&r.maxFollowers()<r.minFollowers())throw new ApiException(HttpStatus.BAD_REQUEST,"maxFollowers must be greater than or equal to minFollowers");c.setBrand(b);c.setTitle(r.title().trim());c.setDescription(r.description());c.setCategory(r.category().trim());c.setPlatform(r.platform().trim());c.setTargetLocation(r.targetLocation());c.setMinFollowers(r.minFollowers());c.setMaxFollowers(r.maxFollowers());c.setMinEngagement(r.minEngagement());c.setMaxBudget(r.maxBudget());if(r.status()!=null)c.setStatus(r.status());return c;}public CampaignResponse map(Campaign c){return new CampaignResponse(c.getId(),c.getTitle(),c.getDescription(),c.getCategory(),c.getPlatform(),c.getTargetLocation(),c.getMinFollowers(),c.getMaxFollowers(),c.getMinEngagement(),c.getMaxBudget(),c.getStatus(),c.getCreatedAt());}}
